(5737950, 833593, 67237, '<td valign="top">Congrats on the top10! Would you mind to share how you ended up with that color palette?</td>', 'Congrats on the top10! Would you mind to share how you ended up with that color palette?', '2009-11-23 10:59:57.000000', NULL, 0),
(5737955, 833681, 42256, '<td valign="top">Congrats on the first ribbon.. this is beautifully done!</td>', 'Congrats on the first ribbon.. this is beautifully done!', '2009-11-23 11:05:04.000000', NULL, 0),
(5737964, 832997, 58785, '<td valign="top">SUPER!!!</td>', 'SUPER!!!', '2009-11-23 11:11:34.000000', NULL, 0),
(5738038, 833593, 83650, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nutzito:</b></div><hr/><i> Congrats on the top10! Would you mind to share how you ended up with that color palette? </i></td></tr></table> <br/> <br/>Just a few filtered masks and then brushing the colors to my liking.  The sky was fairly close except for the horizon which I helped in the red department.  The water was originally more blue than green.  I wanted the scene to be quite believable.  I think that unless you knew the spot, you would probably know the water isn''t green, but hey, many places in the world it can be green. ;-)</td>', 'Originally posted by nutzito: Congrats on the top10! Would you mind to share how you ended up with that color palette?   Just a few filtered masks and then brushing the colors to my liking.  The sky was fairly close except for the horizon which I helped in the red department.  The water was originally more blue than green.  I wanted the scene to be quite believable.  I think that unless you knew the spot, you would probably know the water isn''t green, but hey, many places in the world it can be green. ;-)', '2009-11-23 11:43:54.000000', NULL, 0),
(5738056, 832997, 44877, '<td valign="top">You are a riot, Roz!! The Fly - fits every challenge. This is a beautiful image (even if it is a bug). And HUGE congratulations on another Blue!! You are on fire, girl. OXO</td>', 'You are a riot, Roz!! The Fly - fits every challenge. This is a beautiful image (even if it is a bug). And HUGE congratulations on another Blue!! You are on fire, girl. OXO', '2009-11-23 11:59:30.000000', NULL, 0),
